    "originalTitle": "Orkhon Runes / Steppe Decree of Modu Chanyu (209–174 BC)",
    "authorOrRuler": "Modu Chanyu",
    "authorTitle": "Qaghan / Chanyu / Khan / Sultan of the Steppes",
    "year": -200,
