    "mediumOrFormat": "Carved Granite Monolith / Royal Paiza Inscription",
    "currentPreservationLocation": "Orkhon Museum, Mongolia / Gur-e-Amir, Samarkand",
    "famousQuote": "O blue sky above, O brown earth below! I did not rule over a wealthy people; I gathered the scattered folk, made the poor rich, and the few many. Hear my words!",
    "summary": "Nomadic epic stela or military decree by Modu Chanyu regarding Xiongnu State Oath: \"Land is the Foundation of the State; How Can We Give It Away?\", recording the fierce independence, martial mobility, and astronomical patronage of the steppe empires.",
