    "fullExcerptText": "When the blue sky was created above and the brown earth below, between them human beings were created. Over human beings my ancestors ruled! They organized and ruled the realm of the Turks. We conquered nations to the east and to the west. If you remain upon the sacred forest of Otuken, sending caravans to trade, you shall never experience grief!",
