    "lastingImpact": "Shaped the geopolitical map of Eurasia from China to Central Europe and the Middle East.",
    "audioSpeechText": "Hear the words of the Qaghan! Under the eternal blue sky, we have unified the tribes. Ride as one, guard our ancestral soil, and let our fame echo across the plains forever!"
